<?php
declare(strict_types=1);

/** Additive Pakistan-ready ERP foundations. Existing records and identifiers are preserved. */
return static function (PDO $pdo): void {
    $column = static function (string $table, string $name, string $definition) use ($pdo): void {
        $q = $pdo->prepare('SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c');
        $q->execute(['t' => $table, 'c' => $name]);
        if (!$q->fetchColumn()) $pdo->exec("ALTER TABLE `{$table}` ADD COLUMN `{$name}` {$definition}");
    };

    $pdo->exec("CREATE TABLE IF NOT EXISTS academic_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,status ENUM('planned','active','closed') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_academic_session(institute_id,name),INDEX idx_session_status(institute_id,status),CONSTRAINT fk_session_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS academic_rule_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,session_id BIGINT UNSIGNED NULL,name VARCHAR(120) NOT NULL,institute_type ENUM('internal','coaching','fbise','provincial_bise','custom') NOT NULL DEFAULT 'coaching',board_name VARCHAR(120) NULL,min_attendance DECIMAL(5,2) NOT NULL DEFAULT 0,pass_threshold DECIMAL(5,2) NOT NULL DEFAULT 40,absent_counts_as_zero TINYINT(1) NOT NULL DEFAULT 0,is_default TINYINT(1) NOT NULL DEFAULT 0,effective_from DATE NULL,effective_to DATE NULL,applicable_levels VARCHAR(255) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_rule_profile(institute_id,name),CONSTRAINT fk_rule_profile_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_rule_profile_session FOREIGN KEY(session_id) REFERENCES academic_sessions(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS academic_profile_grades(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,profile_id BIGINT UNSIGNED NOT NULL,label VARCHAR(12) NOT NULL,min_percentage DECIMAL(5,2) NOT NULL,max_percentage DECIMAL(5,2) NOT NULL,result_status ENUM('pass','fail','ungraded') NOT NULL DEFAULT 'pass',description VARCHAR(120) NULL,sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0,UNIQUE KEY uq_profile_grade(profile_id,label),CONSTRAINT fk_profile_grade FOREIGN KEY(profile_id) REFERENCES academic_rule_profiles(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS class_sections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,name VARCHAR(40) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_class_section(class_id,name),CONSTRAINT fk_section_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_section_class FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS academic_streams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,name VARCHAR(80) NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_stream(institute_id,name),CONSTRAINT fk_stream_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $column('students','section_id','BIGINT UNSIGNED NULL AFTER class_id');
    $column('students','stream_id','BIGINT UNSIGNED NULL AFTER section_id');
    $column('students','nationality',"VARCHAR(80) NULL DEFAULT 'Pakistani'");
    $column('students','guardian_name','VARCHAR(160) NULL');
    $column('students','guardian_nic','VARCHAR(100) NULL');
    $column('students','guardian_mobile','VARCHAR(50) NULL');
    $column('students','board_registration_no','VARCHAR(100) NULL');
    $column('students','board_roll_no','VARCHAR(100) NULL');
    $column('students','previous_board','VARCHAR(120) NULL');
    $column('students','archived_at','DATETIME NULL');
    $column('subjects','subject_type',"ENUM('compulsory','elective','practical','theory','theory_practical','internal') NOT NULL DEFAULT 'theory'");

    $pdo->exec("CREATE TABLE IF NOT EXISTS teacher_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,employee_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NULL,section_id BIGINT UNSIGNED NULL,assignment_type ENUM('whole_class','subject','homeroom') NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_teacher_scope(employee_id,class_id,subject_id,section_id,assignment_type),INDEX idx_teacher_scope(institute_id,class_id,subject_id,status),CONSTRAINT fk_teacher_assignment_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_teacher_assignment_employee FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE,CONSTRAINT fk_teacher_assignment_class FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,CONSTRAINT fk_teacher_assignment_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,CONSTRAINT fk_teacher_assignment_section FOREIGN KEY(section_id) REFERENCES class_sections(id) ON DELETE CASCADE,CONSTRAINT fk_teacher_assignment_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS guardians(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,name VARCHAR(160) NOT NULL,relationship VARCHAR(40) NOT NULL DEFAULT 'Guardian',cnic VARCHAR(100) NULL,mobile VARCHAR(50) NOT NULL,email VARCHAR(190) NULL,address TEXT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_guardian_lookup(institute_id,mobile,cnic),CONSTRAINT fk_guardian_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS guardian_students(guardian_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,is_primary TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,PRIMARY KEY(guardian_id,student_id),CONSTRAINT fk_guardian_student_guardian FOREIGN KEY(guardian_id) REFERENCES guardians(id) ON DELETE CASCADE,CONSTRAINT fk_guardian_student_student FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS guardian_accounts(guardian_id BIGINT UNSIGNED PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL UNIQUE,created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_guardian_account_guardian FOREIGN KEY(guardian_id) REFERENCES guardians(id) ON DELETE CASCADE,CONSTRAINT fk_guardian_account_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_guardian_account_creator FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    $pdo->exec("ALTER TABLE student_attendance MODIFY status ENUM('Present','Absent','Late','Leave') NOT NULL");
    $column('student_attendance','check_in_time','TIME NULL AFTER status');
    $pdo->exec("CREATE TABLE IF NOT EXISTS institute_holidays(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,holiday_date DATE NOT NULL,name VARCHAR(120) NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_holiday(institute_id,holiday_date),CONSTRAINT fk_holiday_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    $pdo->exec("CREATE TABLE IF NOT EXISTS class_notes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,class_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,teacher_id BIGINT UNSIGNED NULL,chapter VARCHAR(120) NULL,title VARCHAR(160) NOT NULL,description TEXT NULL,attachment_path VARCHAR(255) NULL,publish_date DATE NOT NULL,status ENUM('draft','published') NOT NULL DEFAULT 'published',created_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,INDEX idx_notes_scope(institute_id,class_id,subject_id,publish_date),CONSTRAINT fk_notes_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_notes_class FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE,CONSTRAINT fk_notes_subject FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE,CONSTRAINT fk_notes_teacher FOREIGN KEY(teacher_id) REFERENCES employees(id) ON DELETE SET NULL,CONSTRAINT fk_notes_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $column('homework','title',"VARCHAR(160) NOT NULL DEFAULT 'Homework'");
    $column('homework','status',"ENUM('draft','published') NOT NULL DEFAULT 'published'");
    $column('homework','institute_id','BIGINT UNSIGNED NULL');
    $pdo->exec('UPDATE homework h JOIN classes c ON c.id=h.class_id SET h.institute_id=c.institute_id WHERE h.institute_id IS NULL');

    $column('class_tests','test_type',"ENUM('quiz','class_test','monthly_test','assignment') NOT NULL DEFAULT 'class_test'");
    $column('class_tests','teacher_id','BIGINT UNSIGNED NULL');
    $column('class_tests','passing_marks','DECIMAL(8,2) NULL');
    $column('class_tests','description','TEXT NULL');
    $column('class_tests','status',"ENUM('draft','published','completed') NOT NULL DEFAULT 'draft'");
    $column('class_test_marks','is_absent','TINYINT(1) NOT NULL DEFAULT 0');
    $column('class_test_marks','remarks','VARCHAR(255) NULL');
    $column('exams','exam_type',"VARCHAR(60) NOT NULL DEFAULT 'Internal'");
    $column('exams','session_id','BIGINT UNSIGNED NULL');
    $column('exams','rule_profile_id','BIGINT UNSIGNED NULL');
    $column('exams','status',"ENUM('draft','marks_entered','calculated','published','locked') NOT NULL DEFAULT 'draft'");
    $column('exam_marks','is_absent','TINYINT(1) NOT NULL DEFAULT 0');

    $pdo->exec("CREATE TABLE IF NOT EXISTS fee_settings(institute_id BIGINT UNSIGNED PRIMARY KEY,generation_day TINYINT UNSIGNED NOT NULL DEFAULT 1,admission_month_policy ENUM('current_month','next_month') NOT NULL DEFAULT 'current_month',due_day TINYINT UNSIGNED NULL,voucher_copies ENUM('single','student_institute','three_copy') NOT NULL DEFAULT 'single',payment_methods_json TEXT NULL,updated_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,CONSTRAINT fk_fee_settings_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS fee_generation_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,billing_month CHAR(7) NOT NULL,generated_count INT UNSIGNED NOT NULL DEFAULT 0,skipped_count INT UNSIGNED NOT NULL DEFAULT 0,triggered_by BIGINT UNSIGNED NULL,source ENUM('cron','manual','admission') NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_fee_generation(institute_id,billing_month,source),CONSTRAINT fk_fee_run_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $column('fee_invoices','due_date','DATE NULL');
    $column('fee_invoices','voided_at','DATETIME NULL');
    $column('fee_invoices','voided_by','BIGINT UNSIGNED NULL');
    $column('fee_invoices','void_reason','VARCHAR(255) NULL');
    $column('fee_payments','remarks','VARCHAR(255) NULL');
    $column('fee_payments','reversed_at','DATETIME NULL');
    $column('fee_payments','reversed_by','BIGINT UNSIGNED NULL');
    $column('fee_payments','reversal_reason','VARCHAR(255) NULL');

    $pdo->exec("CREATE TABLE IF NOT EXISTS whatsapp_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(60) NOT NULL,name VARCHAR(120) NOT NULL,body TEXT NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,UNIQUE KEY uq_whatsapp_template(institute_id,event_key),CONSTRAINT fk_wa_template_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS whatsapp_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,template_id BIGINT UNSIGNED NULL,recipient_type VARCHAR(30) NOT NULL,recipient_id BIGINT UNSIGNED NULL,normalized_phone VARCHAR(30) NOT NULL,message_hash CHAR(64) NOT NULL,mode ENUM('click','provider') NOT NULL,delivery_status ENUM('opened','queued','sent','failed','not_configured') NOT NULL,provider_reference VARCHAR(120) NULL,error_message VARCHAR(255) NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL,INDEX idx_wa_log(institute_id,created_at),CONSTRAINT fk_wa_log_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_wa_log_template FOREIGN KEY(template_id) REFERENCES whatsapp_templates(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institute_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED NULL,metadata_json TEXT NULL,created_at DATETIME NOT NULL,INDEX idx_audit_entity(institute_id,entity_type,entity_id),INDEX idx_audit_time(institute_id,created_at),CONSTRAINT fk_audit_institute FOREIGN KEY(institute_id) REFERENCES institutes(id) ON DELETE CASCADE,CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");

    $now=date('Y-m-d H:i:s');
    $pdo->exec("INSERT IGNORE INTO roles(name,slug,created_at,updated_at) VALUES('Parent / Guardian','parent','{$now}','{$now}')");
    $pdo->exec("INSERT IGNORE INTO permissions(name,slug,created_at,updated_at) VALUES('Parent portal access','portal.parent','{$now}','{$now}'),('Manage teacher assignments','teacher-assignments.manage','{$now}','{$now}'),('View notes','notes.view','{$now}','{$now}'),('Manage notes','notes.manage','{$now}','{$now}'),('Manage WhatsApp','whatsapp.manage','{$now}','{$now}')");
    $pdo->exec("INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.slug='portal.parent' WHERE r.slug='parent'");
    $pdo->exec("INSERT IGNORE INTO fee_settings(institute_id,payment_methods_json,created_at,updated_at) SELECT id,'[\"Cash\",\"Bank\",\"Online Transfer\",\"Cheque\",\"JazzCash\",\"Easypaisa\",\"Other\"]','{$now}','{$now}' FROM institutes");
};
